// Public Storefront credentials; never put an Admin or private token here.
export const shopConfig = {
  domain: "other-dev-xwvzitvq.myshopify.com",
  token: "3594d690353b2cb8846be866204a4369",
  productId: "gid://shopify/Product/15463489208474",
  capsuleReady: true,
};

const cartFields = `id totalQuantity checkoutUrl cost { subtotalAmount { amount currencyCode } }
  lines(first: 100) { nodes { id quantity cost { totalAmount { amount currencyCode } }
    merchandise { ... on ProductVariant { id title product { title } image { url altText } } } } }`;
const storageKey = `other-cart:${shopConfig.domain}`;
let cart = null;
let dialog;
let list;
let status;
let subtotal;
let checkout;
let cartButton;
let busy = false;
let ready;
let product;
let returnFocus;

async function api(query, variables = {}) {
  const response = await fetch(`https://${shopConfig.domain}/api/2026-07/graphql.json`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-Shopify-Storefront-Access-Token": shopConfig.token },
    body: JSON.stringify({ query, variables }),
    signal: AbortSignal.timeout(15000),
  });
  if (!response.ok) throw new Error("The shop is unavailable. Please try again.");
  const result = await response.json();
  if (result.errors?.length) throw new Error(result.errors.map((error) => error.message).join(" "));
  return result.data;
}

function storedId() {
  try { return localStorage.getItem(storageKey); } catch { return null; }
}

function saveCart(value) {
  cart = value;
  try {
    if (cart) localStorage.setItem(storageKey, cart.id);
    else localStorage.removeItem(storageKey);
  } catch { /* The cart still works for this visit when storage is blocked. */ }
}

async function refreshCart() {
  const id = cart?.id || storedId();
  if (id) saveCart((await api(`query($id: ID!) { cart(id: $id) { ${cartFields} } }`, { id })).cart);
}

async function mutate(name, declarations, args, variables) {
  const result = (await api(`mutation(${declarations}) { ${name}(${args}) {
    cart { ${cartFields} } userErrors { message } warnings { message }
  } }`, variables))[name];
  if (result.cart) saveCart(result.cart);
  if (result.userErrors.length) throw new Error(result.userErrors.map((error) => error.message).join(" "));
  status.textContent = result.warnings.map((warning) => warning.message).join(" ");
}

function node(tag, text, parent) {
  const element = document.createElement(tag);
  if (text) element.textContent = text;
  parent?.append(element);
  return element;
}

function money(value) {
  return new Intl.NumberFormat("en-GB", { style: "currency", currency: value.currencyCode }).format(Number(value.amount));
}

function render() {
  list.replaceChildren();
  cartButton.textContent = `Cart (${cart?.totalQuantity || 0})`;
  const lines = (cart?.lines.nodes || []).filter((line) => line.quantity > 0);
  if (!lines.length) node("p", "Your cart is empty.", list);
  for (const line of lines) {
    const row = node("article", "", list);
    row.className = "other-cart-line";
    const variant = line.merchandise;
    if (variant.image) {
      const image = node("img", "", row);
      image.src = variant.image.url;
      image.alt = variant.image.altText || variant.product.title;
    }
    const details = node("div", "", row);
    node("h3", variant.product.title, details);
    if (variant.title !== "Default Title") node("p", variant.title, details);
    node("p", money(line.cost.totalAmount), details);
    const controls = node("div", "", details);
    controls.className = "other-cart-quantity";
    for (const [label, quantity, accessible] of [["−", line.quantity - 1, "Decrease quantity"], ["+", line.quantity + 1, "Increase quantity"]]) {
      if (label === "+") node("span", String(line.quantity), controls);
      const button = node("button", label, controls);
      button.type = "button";
      button.setAttribute("aria-label", `${accessible}: ${variant.product.title}`);
      button.disabled = busy;
      button.onclick = () => run(() => changeQuantity(line.id, quantity));
    }
    const remove = node("button", "Remove", details);
    remove.type = "button";
    remove.disabled = busy;
    remove.onclick = () => run(() => changeQuantity(line.id, 0));
  }
  subtotal.textContent = cart ? `Subtotal ${money(cart.cost.subtotalAmount)}` : "";
  checkout.disabled = busy || !lines.length;
  dialog.setAttribute("aria-busy", String(busy));
}

async function changeQuantity(id, quantity) {
  if (!quantity) return mutate("cartLinesRemove", "$cartId: ID!, $lineIds: [ID!]!", "cartId: $cartId, lineIds: $lineIds", { cartId: cart.id, lineIds: [id] });
  return mutate("cartLinesUpdate", "$cartId: ID!, $lines: [CartLineUpdateInput!]!", "cartId: $cartId, lines: $lines", { cartId: cart.id, lines: [{ id, quantity }] });
}

async function run(operation) {
  if (busy) return;
  busy = true;
  status.textContent = "";
  render();
  try { await operation(); }
  catch (error) { status.textContent = error.message || "Something went wrong. Please try again."; }
  finally { busy = false; render(); }
}

function openCart() {
  if (!dialog.open) {
    returnFocus = document.activeElement;
    dialog.showModal();
  }
}

export function initShopifyCart() {
  if (!shopConfig.capsuleReady || dialog) return;
  const style = node("style", "", document.head);
  style.textContent = `
    .other-cart { position:fixed; inset:0 0 0 auto; margin:0; width:min(460px,100%); max-width:100%; height:100dvh; max-height:100dvh; box-sizing:border-box; padding:24px; border:0; background:#edff00; color:#08006b; overflow:auto; font:16px/1.4 Arial,sans-serif; }
    .other-cart::backdrop { background:rgba(0,0,0,.4); }
    .other-cart header { display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid; margin-bottom:24px; }
    .other-cart h2 { font-size:24px; } .other-cart h3 { font-size:18px; margin:0; }
    .other-cart button { cursor:pointer; padding:8px 12px; color:inherit; background:transparent; border:1px solid currentColor; font:inherit; }
    .other-cart button:disabled { opacity:.45; cursor:wait; }
    .other-cart-line { display:flex; gap:16px; padding:20px 0; border-bottom:1px solid; }
    .other-cart-line img { width:80px; height:120px; object-fit:contain; }
    .other-cart-line > div { min-width:0; overflow-wrap:anywhere; }
    .other-cart-quantity { display:flex; gap:14px; align-items:center; margin:12px 0; }
    .other-cart-status { min-height:24px; }
    .other-cart .other-checkout { width:100%; background:#08006b; color:#edff00; padding:16px; }
    .other-cart-toggle { position:fixed; right:16px; bottom:90px; z-index:30; padding:10px 18px; border:1px solid #edff00; background:#08006b; color:#edff00; font:16px Arial,sans-serif; cursor:pointer; }
  `;
  dialog = node("dialog", "", document.body);
  dialog.className = "other-cart";
  dialog.dataset.lenisPrevent = "";
  dialog.setAttribute("aria-label", "Shopping cart");
  const header = node("header", "", dialog);
  node("h2", "Your cart", header);
  const close = node("button", "×", header);
  close.setAttribute("aria-label", "Close cart");
  close.onclick = () => dialog.close();
  dialog.addEventListener("close", () => returnFocus?.focus?.({ preventScroll: true }));
  list = node("div", "", dialog);
  status = node("p", "", dialog);
  status.className = "other-cart-status";
  status.setAttribute("role", "status");
  subtotal = node("p", "", dialog);
  node("p", "Shipping and taxes calculated at checkout.", dialog);
  checkout = node("button", "Checkout", dialog);
  checkout.className = "other-checkout";
  checkout.onclick = () => run(async () => {
    await refreshCart();
    if (!cart?.totalQuantity) throw new Error("Your cart is empty. Please add your product again.");
    window.location.assign(cart.checkoutUrl);
  });
  cartButton = node("button", "Cart (0)", document.body);
  cartButton.className = "other-cart-toggle";
  cartButton.onclick = () => { openCart(); run(refreshCart); };
  render();
  ready = api(`query($id: ID!) { product(id: $id) { title variants(first: 100) { nodes { id title availableForSale } } } }`, { id: shopConfig.productId })
    .then((data) => { product = data.product; });
  ready.catch(() => {});
  run(refreshCart);
}

export async function buyCapsule() {
  initShopifyCart();
  openCart();
  if (busy) return;
  await run(async () => {
    await ready;
    if (!product) throw new Error("This capsule is not available in the shop yet.");
    const variants = product.variants.nodes.filter((variant) => variant.availableForSale);
    if (!variants.length) throw new Error("This capsule is sold out.");
    if (variants.length > 1) throw new Error("This capsule has multiple options. Product option selection needs to be configured.");
    await refreshCart();
    const lines = [{ merchandiseId: variants[0].id, quantity: 1 }];
    if (cart) await mutate("cartLinesAdd", "$cartId: ID!, $lines: [CartLineInput!]!", "cartId: $cartId, lines: $lines", { cartId: cart.id, lines });
    else await mutate("cartCreate", "$input: CartInput", "input: $input", { input: { lines } });
  });
}
