async function loadLabelTexture(url) {
  const texture = await new THREE.TextureLoader().loadAsync(url);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = THREE.RepeatWrapping;
  texture.offset.x = 0.5;
  texture.anisotropy = 4;
  return texture;
}

function createPhysicalBackdrop(scene) {
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  const material = new THREE.MeshBasicMaterial({ map: texture, toneMapped: false });
  const geometry = new THREE.PlaneGeometry(1, 1);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.visible = true;
  mesh.renderOrder = -1;
  mesh.onBeforeRender = (renderer) => {
    const isTransmissionPass = renderer.getRenderTarget() !== null;
    material.colorWrite = isTransmissionPass;
    material.depthWrite = isTransmissionPass;
  };
  scene.add(mesh);

  const direction = new THREE.Vector3();
  return {
    mesh,
    update(source, color) {
      if (!source) return;
      if (canvas.width !== source.width || canvas.height !== source.height) {
        canvas.width = source.width;
        canvas.height = source.height;
      }
      context.fillStyle = color.getStyle();
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(source, 0, 0);
      texture.needsUpdate = true;
    },
    setVerticalOffset(offset) {
      texture.offset.y = offset;
    },
    position(camera) {
      const distance = 8;
      camera.getWorldDirection(direction);
      mesh.position.copy(camera.position).addScaledVector(direction, distance);
      mesh.quaternion.copy(camera.quaternion);
      const height = 2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * distance;
      mesh.scale.set(height * camera.aspect, height, 1);
    },
    dispose() {
      scene.remove(mesh);
      geometry.dispose();
      material.dispose();
      texture.dispose();
    },
  };
}

function waitForLogoSource(element) {
  const findSource = () => element.querySelector("svg, img[data-static-hero-logo]");
  const existing = findSource();
  if (existing) return Promise.resolve(existing);

  return new Promise((resolve) => {
    const observer = new MutationObserver(() => {
      const source = findSource();
      if (!source) return;

      observer.disconnect();
      resolve(source);
    });

    observer.observe(element, { childList: true, subtree: true });
    window.setTimeout(() => {
      observer.disconnect();
      resolve(findSource());
    }, 5000);
  });
}

async function createLogoTexture(source, logoElement, mount, settings) {
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  resizeLogoCanvas(canvas, mount, settings);
  const logoImage = await drawLogoToCanvas(source, logoElement, mount, canvas, context, settings);

  const texture = new THREE.CanvasTexture(canvas);
  texture.userData.logoImage = logoImage;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.anisotropy = 1;
  texture.premultiplyAlpha = true;
  texture.needsUpdate = true;
  return texture;
}

async function drawLogoToCanvas(source, logoElement, mount, canvas, context, settings) {
  resizeLogoCanvas(canvas, mount, settings);

  if (source instanceof HTMLImageElement) {
    if (!source.complete || !source.naturalWidth) await source.decode();
    drawLogoImage(source, logoElement, mount, canvas, context, settings);
    return source;
  }

  const clone = source.cloneNode(true);
  const logoRect = getLogoPixelRect(logoElement, mount, settings);
  clone.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  clone.setAttribute("width", String(logoRect.width));
  clone.setAttribute("height", String(logoRect.height));
  inlineSvgPaint(source, clone);
  clone.style.filter = "";
  clone.querySelectorAll('filter[id^="logo-jitter-"]').forEach((filter) => filter.remove());
  clone.querySelectorAll('[filter^="url(#logo-jitter-"]').forEach((element) => element.removeAttribute("filter"));

  const svgText = new XMLSerializer().serializeToString(clone);
  const blob = new Blob([svgText], { type: "image/svg+xml" });
  const url = URL.createObjectURL(blob);

  try {
    const image = await loadImage(url);
    drawLogoImage(image, logoElement, mount, canvas, context, settings);
    return image;
  } finally {
    URL.revokeObjectURL(url);
  }
}

function drawLogoImage(image, logoElement, mount, canvas, context, settings) {
  const rect = getLogoPixelRect(logoElement, mount, settings);
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.drawImage(image, rect.x, rect.y, rect.width, rect.height);
}

function createLiquidLogoTexture(initialImage, logoElement, mount, settings, initialRoughness) {
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  const blurredImage = document.createElement("canvas");
  const blurredContext = blurredImage.getContext("2d");
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.premultiplyAlpha = true;
  let image = initialImage;
  let roughness = initialRoughness;

  function position() {
    resizeLogoCanvas(canvas, mount, settings);
    drawLogoImage(roughness > 0 ? blurredImage : image, logoElement, mount, canvas, context, settings);
    texture.needsUpdate = true;
  }

  function refreshBlur() {
    blurredImage.width = image.naturalWidth;
    blurredImage.height = image.naturalHeight;
    blurredContext.clearRect(0, 0, blurredImage.width, blurredImage.height);
    blurredContext.filter = roughness > 0 ? `blur(${18 * roughness}px)` : "none";
    blurredContext.drawImage(image, 0, 0);
    blurredContext.filter = "none";
    position();
  }

  function setRoughness(value) {
    roughness = value;
    refreshBlur();
  }

  texture.userData.setRoughness = setRoughness;
  refreshBlur();
  return {
    texture,
    position,
    updateImage(nextImage) {
      image = nextImage;
      refreshBlur();
    },
    dispose() { texture.dispose(); },
  };
}

function getLogoRectKey(logoElement, mount, settings) {
  const rect = getLogoPixelRect(logoElement, mount, settings);
  return `${rect.x},${rect.y},${rect.width},${rect.height}`;
}

function getLogoTextureMultiplier(mount, settings) {
  const rect = mount.getBoundingClientRect();
  return Math.min(
    Math.min(window.devicePixelRatio || 1, 2) * settings.logoTextureScale,
    settings.logoTextureMaxWidth / Math.max(rect.width, 1),
    settings.logoTextureMaxHeight / Math.max(rect.height, 1),
  );
}

function resizeLogoCanvas(canvas, mount, settings) {
  const rect = mount.getBoundingClientRect();
  const multiplier = getLogoTextureMultiplier(mount, settings);
  const width = Math.max(1, Math.round(rect.width * multiplier));
  const height = Math.max(1, Math.round(rect.height * multiplier));

  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }
}

function getLogoPixelRect(logoElement, mount, settings) {
  const logoRect = logoElement.getBoundingClientRect();
  const mountRect = mount.getBoundingClientRect();
  const multiplier = getLogoTextureMultiplier(mount, settings);

  return {
    x: Math.round((logoRect.left - mountRect.left) * multiplier),
    y: Math.round((logoRect.top - mountRect.top) * multiplier),
    width: Math.max(1, Math.round(logoRect.width * multiplier)),
    height: Math.max(1, Math.round(logoRect.height * multiplier)),
  };
}

function inlineSvgPaint(sourceSvg, cloneSvg) {
  const sourceElements = [sourceSvg, ...sourceSvg.querySelectorAll("*")];
  const cloneElements = [cloneSvg, ...cloneSvg.querySelectorAll("*")];

  sourceElements.forEach((source, index) => {
    const clone = cloneElements[index];
    if (!clone) return;

    const style = window.getComputedStyle(source);
    const fill = source.getAttribute("fill");
    const stroke = source.getAttribute("stroke");

    if (!fill || fill === "currentColor") {
      clone.setAttribute("fill", style.fill || style.color);
    }

    if (stroke === "currentColor") {
      clone.setAttribute("stroke", style.stroke || style.color);
    }
  });
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = src;
  });
}

function frameModel(root) {
  const box = new THREE.Box3().setFromObject(root);
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const maxAxis = Math.max(size.x, size.y, size.z) || 1;
  const targetSize = 2.8;

  root.position.sub(center);
  root.scale.multiplyScalar(targetSize / maxAxis);
}

function disposeModel(root) {
  const geometries = new Set();
  const materials = new Set();
  const textures = new Set();

  root.traverse((child) => {
    if (child.geometry) geometries.add(child.geometry);

    const entries = Array.isArray(child.material) ? child.material : [child.material];
    entries.filter(Boolean).forEach((material) => {
      materials.add(material);
      Object.values(material).forEach((value) => {
        if (value?.isTexture) textures.add(value);
      });
    });
  });

  textures.forEach((texture) => texture.dispose());
  materials.forEach((material) => material.dispose());
  geometries.forEach((geometry) => geometry.dispose());
}
