const DEFAULT_OPTIONS = {
  amount: 5,
  frequency: 0.03,
  fps: 12,
  octaves: 1,
  speed: 1,
  color: "",
  selector: ".hero_logo",
};

const instances = new WeakMap();
let filterCount = 0;

export function initLogoJitter(root = document, options = {}) {
  const settings = { ...DEFAULT_OPTIONS, ...options };
  const containers = root.querySelectorAll?.(settings.selector);

  containers?.forEach((container) => {
    if (instances.has(container)) return;

    const instance = createJitterInstance(container, settings);
    instances.set(container, instance);
    instance.start();
  });
}

export function destroyLogoJitter(root = document) {
  root.querySelectorAll?.(DEFAULT_OPTIONS.selector).forEach((container) => {
    instances.get(container)?.destroy();
    instances.delete(container);
  });
}

function createJitterInstance(container, settings) {
  const options = getElementOptions(container, settings);
  let intervalId = 0;
  let inactivityTimeout = 0;
  let observer = null;
  let seed = Math.floor(Math.random() * 1000);
  let turbulence = null;
  let targetSvg = null;
  const interval = 1000 / options.fps;
  const filterId = `logo-jitter-${++filterCount}`;
  const activityEvents = ["pointermove", "scroll", "keydown", "touchstart"];
  const activityOptions = { passive: true };

  const noteActivity = () => {
    clearTimeout(inactivityTimeout);
    if (!intervalId && turbulence) intervalId = window.setInterval(tick, interval);
    inactivityTimeout = window.setTimeout(() => {
      clearInterval(intervalId);
      intervalId = 0;
    }, 10000);
  };

  const start = () => {
    applyWhenReady();
    observer = new MutationObserver(applyWhenReady);
    observer.observe(container, { childList: true, subtree: true });
    activityEvents.forEach((eventName) => window.addEventListener(eventName, noteActivity, activityOptions));
  };

  const applyWhenReady = () => {
    const svg = container.querySelector("svg");
    if (!svg || svg === targetSvg) return;

    targetSvg = svg;
    turbulence = installFilter(svg, filterId, options);
    applyColor(svg, options.color);
    svg.style.filter = `url(#${filterId})`;
    svg.style.overflow = "visible";

    clearInterval(intervalId);
    intervalId = window.setInterval(tick, interval);
    noteActivity();
  };

  const tick = () => {
    if (!turbulence) return;
    seed += options.speed;
    turbulence.setAttribute("seed", String(Math.floor(seed)));
  };

  const destroy = () => {
    clearInterval(intervalId);
    clearTimeout(inactivityTimeout);
    activityEvents.forEach((eventName) => window.removeEventListener(eventName, noteActivity, activityOptions));
    observer?.disconnect();
    if (targetSvg) {
      targetSvg.style.filter = "";
    }
  };

  return { start, destroy };
}

function getElementOptions(element, defaults) {
  return {
    ...defaults,
    amount: readNumber(element, "logoJitterAmount", defaults.amount),
    frequency: readNumber(element, "logoJitterFrequency", defaults.frequency),
    fps: readNumber(element, "logoJitterFps", defaults.fps),
    octaves: readInteger(element, "logoJitterOctaves", defaults.octaves),
    speed: readNumber(element, "logoJitterSpeed", defaults.speed),
    color: element.dataset.logoJitterColor || defaults.color,
  };
}

function readNumber(element, key, fallback) {
  const value = Number.parseFloat(element.dataset[key]);
  return Number.isFinite(value) ? value : fallback;
}

function readInteger(element, key, fallback) {
  const value = Math.round(readNumber(element, key, fallback));
  return Math.max(1, value);
}

function installFilter(svg, filterId, settings) {
  const namespace = "http://www.w3.org/2000/svg";
  const defs = svg.querySelector("defs") || svg.insertBefore(document.createElementNS(namespace, "defs"), svg.firstChild);
  const previous = defs.querySelector(`#${CSS.escape(filterId)}`);
  previous?.remove();

  const filter = document.createElementNS(namespace, "filter");
  filter.setAttribute("id", filterId);
  filter.setAttribute("x", "-20%");
  filter.setAttribute("y", "-40%");
  filter.setAttribute("width", "140%");
  filter.setAttribute("height", "180%");
  filter.setAttribute("color-interpolation-filters", "sRGB");

  const turbulence = document.createElementNS(namespace, "feTurbulence");
  turbulence.setAttribute("type", "fractalNoise");
  turbulence.setAttribute("baseFrequency", String(settings.frequency));
  turbulence.setAttribute("numOctaves", String(settings.octaves));
  turbulence.setAttribute("seed", "1");
  turbulence.setAttribute("result", "noise");

  const displacement = document.createElementNS(namespace, "feDisplacementMap");
  displacement.setAttribute("in", "SourceGraphic");
  displacement.setAttribute("in2", "noise");
  displacement.setAttribute("scale", String(settings.amount));
  displacement.setAttribute("xChannelSelector", "R");
  displacement.setAttribute("yChannelSelector", "G");

  filter.append(turbulence, displacement);
  defs.append(filter);

  return turbulence;
}

function applyColor(svg, color) {
  if (!color) return;

  svg.querySelectorAll("path, rect, circle, ellipse, polygon, polyline").forEach((shape) => {
    const fill = shape.getAttribute("fill");
    const stroke = shape.getAttribute("stroke");

    if (fill && fill !== "none") {
      shape.setAttribute("fill", color);
    }

    if (stroke && stroke !== "none") {
      shape.setAttribute("stroke", color);
    }
  });
}
