import { initShopifyCart, buyCapsule, shopConfig } from "./shopify-cart.js";

const instances = new WeakMap();
let nextMenuId = 1;

export function prepareFloatingRegister(root) {
  getHolders(root).forEach((holder) => {
    getTrigger(holder)?.removeAttribute("data-w-id");
    holder.style.removeProperty("visibility");
  });
}

export function initFloatingRegister(root) {
  initShopifyCart();
  getHolders(root).forEach((holder) => {
    if (instances.has(holder)) return;
    const trigger = getTrigger(holder);
    const menu = getMenu(holder);
    if (!trigger || !menu) return;
    if (shopConfig.capsuleReady) {
      (trigger.querySelector("div") || trigger).textContent = "BUY";
      trigger.setAttribute("aria-haspopup", "dialog");
    }

    const gsap = window.gsap;
    const originalTriggerStyle = trigger.getAttribute("style");
    const originalMenuStyle = menu.getAttribute("style");
    let open = false;
    let hidden = false;
    let pointer = { x: window.innerWidth / 2, y: window.innerHeight / 2 };

    Object.assign(trigger.style, { position: "fixed", left: "0px", top: "0px", zIndex: "20" });
    Object.assign(menu.style, { position: "fixed", left: "0px", top: "0px", zIndex: "21", display: "none", pointerEvents: "none" });
    trigger.setAttribute("aria-expanded", "false");
    trigger.setAttribute("aria-controls", menu.id || (menu.id = `floating-register-menu-${nextMenuId++}`));

    const moveX = gsap?.quickTo(trigger, "x", { duration: 0.32, ease: "power2.out" });
    const moveY = gsap?.quickTo(trigger, "y", { duration: 0.32, ease: "power2.out" });

    function nearOtherLink() {
      return [...document.querySelectorAll("a[href], button")].some((link) => {
        if (link === trigger || holder.contains(link)) return false;
        const rect = link.getBoundingClientRect();
        if (!rect.width || !rect.height || getComputedStyle(link).visibility === "hidden") return false;
        const dx = Math.max(rect.left - pointer.x, 0, pointer.x - rect.right);
        const dy = Math.max(rect.top - pointer.y, 0, pointer.y - rect.bottom);
        return Math.hypot(dx, dy) < 44;
      });
    }

    function update() {
      if (open) return;
      const x = Math.max(0, Math.min(window.innerWidth - trigger.offsetWidth, pointer.x - trigger.offsetWidth / 2));
      const y = Math.max(0, Math.min(window.innerHeight - trigger.offsetHeight, pointer.y - trigger.offsetHeight / 2));
      if (moveX && moveY) {
        moveX(x);
        moveY(y);
      } else {
        trigger.style.transform = `translate3d(${x}px, ${y}px, 0) scale(${hidden ? 0 : 1})`;
      }
      const shouldHide = nearOtherLink();
      if (shouldHide === hidden) return;
      hidden = shouldHide;
      trigger.style.pointerEvents = hidden ? "none" : "auto";
      gsap?.to(trigger, {
        scale: hidden ? 0 : 1,
        duration: hidden ? 0.18 : 0.4,
        ease: hidden ? "power2.in" : "back.out(2)",
        overwrite: "auto",
      });
    }

    function close() {
      if (!open) return;
      open = false;
      trigger.setAttribute("aria-expanded", "false");
      const finish = () => {
        menu.style.display = "none";
        menu.style.pointerEvents = "none";
        trigger.style.pointerEvents = "auto";
        trigger.style.visibility = "visible";
        gsap?.set(trigger, { scale: 1 });
        update();
      };
      if (gsap) gsap.to(menu, { opacity: 0, scale: 0.9, duration: 0.16, ease: "power2.in", onComplete: finish });
      else finish();
    }

    function onTriggerClick(event) {
      event.preventDefault();
      event.stopImmediatePropagation();
      if (shopConfig.capsuleReady) {
        buyCapsule();
        return;
      }
      if (open) return;
      open = true;
      trigger.setAttribute("aria-expanded", "true");
      const rect = trigger.getBoundingClientRect();
      menu.style.display = "flex";
      menu.style.pointerEvents = "auto";
      menu.style.left = `${Math.max(12, Math.min(window.innerWidth - menu.offsetWidth - 12, rect.left))}px`;
      menu.style.top = `${Math.max(12, Math.min(window.innerHeight - menu.offsetHeight - 12, rect.top))}px`;
      trigger.style.pointerEvents = "none";
      if (gsap) {
        gsap.killTweensOf(trigger, "scale");
        gsap.set(trigger, { scale: 0, visibility: "hidden" });
        gsap.set(menu, { opacity: 1, scale: 0.97, transformOrigin: "top left" });
        gsap.to(menu, { scale: 1, duration: 0.16, ease: "power2.out" });
      } else {
        menu.style.opacity = "1";
        trigger.style.visibility = "hidden";
      }
      menu.querySelector('input[type="email"]')?.focus({ preventScroll: true });
    }

    function onPointerMove(event) {
      pointer = { x: event.clientX, y: event.clientY };
      update();
    }

    function onDocumentClick(event) {
      if (open && !holder.contains(event.target)) close();
    }

    function onKeyDown(event) {
      if (event.key === "Escape") close();
    }

    trigger.addEventListener("click", onTriggerClick);
    document.addEventListener("pointermove", onPointerMove, { passive: true });
    document.addEventListener("click", onDocumentClick);
    document.addEventListener("keydown", onKeyDown);
    window.addEventListener("resize", update);
    window.addEventListener("scroll", update, { passive: true });
    update();

    instances.set(holder, () => {
      trigger.removeEventListener("click", onTriggerClick);
      document.removeEventListener("pointermove", onPointerMove);
      document.removeEventListener("click", onDocumentClick);
      document.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("resize", update);
      window.removeEventListener("scroll", update);
      gsap?.killTweensOf(trigger);
      gsap?.killTweensOf(menu);
      if (originalTriggerStyle === null) trigger.removeAttribute("style");
      else trigger.setAttribute("style", originalTriggerStyle);
      if (originalMenuStyle === null) menu.removeAttribute("style");
      else menu.setAttribute("style", originalMenuStyle);
    });
  });
}

export function destroyFloatingRegister(root) {
  getHolders(root).forEach((holder) => {
    instances.get(holder)?.();
    instances.delete(holder);
  });
}

export function hideFloatingRegister(root) {
  getHolders(root).forEach((holder) => { holder.style.visibility = "hidden"; });
  destroyFloatingRegister(root);
}

function getHolders(root) {
  const holders = new Set(document.querySelectorAll(".floating_menu_holder"));
  root?.querySelectorAll?.(".floating_menu_holder").forEach((holder) => holders.add(holder));
  if (root?.matches?.(".floating_menu_holder")) holders.add(root);
  return [...holders];
}

function getTrigger(holder) {
  return holder.querySelector("[data-floating-register-trigger], a.cta.floating:not(.vert)");
}

function getMenu(holder) {
  return holder.querySelector("[data-floating-register-menu], .cta.floating.vert");
}
