import { setScrollingBannerText } from "./scrolling-banner.js";

let activeNavigation = null;

export function initSectionNavigation({ nav, sectionsRoot, ticker, lenis } = {}) {
  destroySectionNavigation();
  const flex = nav?.querySelector(".flex") || nav;
  if (!flex || !sectionsRoot) return;

  const topSection = sectionsRoot.querySelector("#top");
  const initialTickerText = ticker?.querySelector(".scrolling_banner_inner h5")?.textContent?.trim() || "";
  let sectionsByLink = [];
  let topLink = null;
  let frame = 0;
  let active = null;
  let topLinkActive = null;
  let tickerSection = null;
  let requested = null;
  const originalNavPosition = nav.style.position;
  const originalNavZIndex = nav.style.zIndex;
  if (getComputedStyle(nav).position === "static") nav.style.position = "relative";
  nav.style.zIndex = "5";

  const syncNavItems = () => {
    const allButtons = [...flex.querySelectorAll("a.cta.round[href]")];
    topLink = allButtons[0] || null;
    const existingLinks = allButtons.length
      ? allButtons.slice(1)
      : [...flex.querySelectorAll('a[href^="#"]')].slice(1);
    const linksById = new Map();
    existingLinks.forEach((link) => {
      const id = decodeHash(link.getAttribute("href"));
      if (!id) return;
      if (!linksById.has(id)) linksById.set(id, []);
      linksById.get(id).push(link);
    });

    const template = existingLinks[0] || null;
    const sectionEntries = [...sectionsRoot.querySelectorAll(".section[id]")]
      .filter((section) => section.classList.length === 1)
      .map((section) => ({
      id: section.id,
      section,
      label: getSectionLabel(section),
      }));
    const retained = new Set();

    sectionEntries.forEach((entry) => {
      const matching = linksById.get(entry.id)?.find((candidate) => !retained.has(candidate));
      const link = matching || existingLinks.find((candidate) => !retained.has(candidate)) || createLink(template);
      retained.add(link);
      link.setAttribute("href", `#${encodeURIComponent(entry.id)}`);
      setLinkLabel(link, entry.label);
      flex.append(link);
    });

    existingLinks.forEach((link) => {
      if (!retained.has(link)) link.remove();
    });

    sectionsByLink = sectionEntries.map((entry) => ({
      ...entry,
      link: [...flex.querySelectorAll("a[href]")].find((link) => decodeHash(link.getAttribute("href")) === entry.id),
    })).filter((entry) => entry.link);
    active = null;
    updateFromScroll();
  };

  const select = (entry) => {
    if (!entry) return;
    setActiveNavigationLink(entry, false);
    if (tickerSection !== entry && entry.section.id !== "top") {
      tickerSection = entry;
      setScrollingBannerText(ticker, getSectionLabel(entry.section).toUpperCase());
    }
  };

  const updateNavGradient = () => {
    if (!topSection) return;
    const reveal = clamp01((window.innerHeight - topSection.getBoundingClientRect().bottom) / Math.max(window.innerHeight, 1));
    nav.style.setProperty("--nav-gradient-opacity", reveal.toFixed(3));
    nav.style.setProperty("--nav-gradient-y", `${(-90 * (1 - reveal)).toFixed(1)}px`);
    nav.classList.toggle("nav--past-top", reveal > 0);
  };

  function updateFromScroll() {
    updateNavGradient();
    cancelAnimationFrame(frame);
    frame = requestAnimationFrame(() => {
      const marker = window.innerHeight * 0.72;
      const matching = sectionsByLink.find(({ section }) => {
        const bounds = section.getBoundingClientRect();
        return bounds.top <= marker && bounds.bottom > marker;
      });
      if (requested) {
        const bounds = requested.section.getBoundingClientRect();
        if (bounds.top <= marker && bounds.bottom > marker) requested = null;
        else return;
      }
      const previous = [...sectionsByLink].reverse().find(({ section }) => section.getBoundingClientRect().top <= marker);
      const current = matching || previous;
      if (current) {
        const topBounds = topSection?.getBoundingClientRect();
        const isTopActive = Boolean(topBounds && topBounds.top <= marker && topBounds.bottom > marker);
        setActiveNavigationLink(current, isTopActive);
        if (!isTopActive && tickerSection !== current && current.section.id !== "top") {
          tickerSection = current;
          setScrollingBannerText(ticker, getSectionLabel(current.section).toUpperCase());
        }
      } else {
        tickerSection = null;
        setActiveNavigationLink(null, true);
        setScrollingBannerText(ticker, initialTickerText);
      }
    });
  }

  const onClick = (event) => {
    const link = event.target.closest("a[href]");
    if (!link || !flex.contains(link)) return;
    if (link === topLink) {
      setActiveNavigationLink(null, true);
      requested = null;
      updateFromScroll();
      return;
    }
    const entry = sectionsByLink.find((item) => item.link === link);
    if (!entry) return;
    requested = entry;
    cancelAnimationFrame(frame);
    select(entry);
    updateFromScroll();
  };

  function setActiveNavigationLink(entry, isTopActive = false) {
    if (active === entry && topLinkActive === isTopActive) return;
    active = entry;
    topLinkActive = isTopActive;
    if (topLink) {
      topLink.classList.toggle("w--current", isTopActive);
      if (isTopActive) topLink.setAttribute("aria-current", "page");
      else topLink.removeAttribute("aria-current");
    }
    sectionsByLink.forEach(({ link }) => {
      const isActive = !isTopActive && Boolean(entry) && link === entry.link;
      link.classList.toggle("w--current", isActive);
      if (isActive) link.setAttribute("aria-current", "location");
      else link.removeAttribute("aria-current");
    });
  }
  const onManualScroll = () => { requested = null; };
  const onHashChange = () => {
    const match = sectionsByLink.find(({ id }) => `#${id}` === window.location.hash);
    if (match) select(match);
    updateFromScroll();
  };

  syncNavItems();
  flex.addEventListener("click", onClick);
  window.addEventListener("scroll", updateFromScroll, { passive: true });
  window.addEventListener("resize", updateFromScroll, { passive: true });
  window.addEventListener("hashchange", onHashChange);
  window.addEventListener("wheel", onManualScroll, { passive: true });
  window.addEventListener("touchstart", onManualScroll, { passive: true });
  lenis?.on?.("scroll", updateFromScroll);

  const sectionObserver = new MutationObserver((records) => {
    if (records.some((record) => !nav?.contains(record.target))) syncNavItems();
  });
  sectionObserver.observe(sectionsRoot, { childList: true, subtree: true });

  activeNavigation = () => {
    cancelAnimationFrame(frame);
    sectionObserver.disconnect();
    nav.classList.remove("nav--past-top");
    nav.style.removeProperty("--nav-gradient-opacity");
    nav.style.removeProperty("--nav-gradient-y");
    nav.style.position = originalNavPosition;
    nav.style.zIndex = originalNavZIndex;
    flex.removeEventListener("click", onClick);
    window.removeEventListener("scroll", updateFromScroll);
    window.removeEventListener("resize", updateFromScroll);
    window.removeEventListener("hashchange", onHashChange);
    window.removeEventListener("wheel", onManualScroll);
    window.removeEventListener("touchstart", onManualScroll);
    lenis?.off?.("scroll", updateFromScroll);
  };
}

function getSectionLabel(section) {
  const explicit = section.dataset.navLabel || section.getAttribute("aria-label");
  const heading = section.querySelector(".feature_headings h3, [data-nav-heading], h1, h2, h3, h4, h5, h6");
  return (explicit || heading?.textContent || section.id.replace(/[-_]+/g, " ")).trim().replace(/\s+/g, " ");
}

function setLinkLabel(link, label) {
  const target = link.querySelector(":scope > div") || link;
  if (target.textContent.trim() !== label) target.textContent = label;
}

function createLink(template) {
  if (template) {
    const link = template.cloneNode(true);
    link.classList.remove("w--current");
    link.removeAttribute("aria-current");
    return link;
  }
  const link = document.createElement("a");
  link.className = "cta round w-inline-block";
  link.append(document.createElement("div"));
  return link;
}

function decodeHash(href) {
  if (!href?.startsWith("#")) return "";
  try {
    return decodeURIComponent(href.slice(1));
  } catch {
    return href.slice(1);
  }
}

function clamp01(value) {
  return Math.min(1, Math.max(0, value));
}

export function destroySectionNavigation() {
  activeNavigation?.();
  activeNavigation = null;
}
