import { initBarba } from "./modules/barba.js";
import { installUnderlineLinkStyles } from "./modules/text-animations.js";
import { initThreeScene } from "./modules/three-scene.js";
import { destroyLinkHover, initLinkHover } from "./modules/link-hover.js";
import { destroyLogoJitter, initLogoJitter } from "./modules/logo-jitter.js";
import { destroyScrollingBanner, initScrollingBanner } from "./modules/scrolling-banner.js";
import { startLenisRaf } from "./modules/lenis-raf.js";
import { destroySectionNavigation, initSectionNavigation } from "./modules/section-navigation.js";
import { destroySectionParallax, initSectionParallax } from "./modules/section-parallax.js";
import { destroyFloatingRegister, hideFloatingRegister, initFloatingRegister, prepareFloatingRegister } from "./modules/floating-register.js";
import { domReady } from "./utils/dom-ready.js";

const app = { three: null, barba: null, lenis: null };
const BASE_SCRIPT_URL = document.currentScript?.src || "";
let logoLottieControlsPromise = null;
const DIAGNOSTIC_FLAGS = new URLSearchParams(window.location.search);
const ENABLE_LOGO_JITTER = !DIAGNOSTIC_FLAGS.has("nojitter");
const DISABLE_THREE_FOR_DIAGNOSTICS = DIAGNOSTIC_FLAGS.has("no3d");
const DISABLE_LOGO_JSON_FOR_DIAGNOSTICS = DIAGNOSTIC_FLAGS.has("nojson");
const SAFARI_STATIC_LOGO = isSafari();
installUnderlineLinkStyles();
installNavCurrentStyles();
prepareLogoHost(document);
if (SAFARI_STATIC_LOGO) installStaticLogo(document);

function isSafari() {
  const userAgent = navigator.userAgent;
  return /Safari/i.test(userAgent) && !/(Chrome|Chromium|CriOS|Edg|EdgiOS|OPR|FxiOS|Firefox)/i.test(userAgent);
}

function prepareLogoHost(root) {
  root.querySelectorAll?.(".hero_logo").forEach((container) => {
    container.removeAttribute("data-animation-type");
    container.removeAttribute("data-w-id");
    container.removeAttribute("data-src");
  });
}

function installStaticLogo(root) {
  root.querySelectorAll?.(".hero_logo").forEach((container) => {
    if (container.querySelector("img[data-static-hero-logo]")) return;
    const image = document.createElement("img");
    image.src = "https://cdn.jsdelivr.net/gh/kujira22/other-label-texture@8ad5291/hero-logo.svg";
    image.alt = "";
    image.setAttribute("aria-hidden", "true");
    image.dataset.staticHeroLogo = "";
    image.draggable = false;
    image.style.cssText = "display:block;width:100%;height:100%;object-fit:contain;pointer-events:none";
    image.addEventListener("error", () => console.warn("[logo] Static logo could not be loaded:", image.src), { once: true });
    container.replaceChildren(image);
  });
}

function loadLogoLottieControls() {
  if (logoLottieControlsPromise) return logoLottieControlsPromise;

  logoLottieControlsPromise = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    const isDev = import.meta.env.DEV;
    script.src = isDev ? "/src/logo-lottie-dev.js" : new URL("./logo-lottie.js", BASE_SCRIPT_URL).href;
    if (isDev) script.type = "module";
    script.onload = () => resolve(window.LogoLottieControls);
    script.onerror = () => reject(new Error("The optional Lottie controls script could not be loaded."));
    document.head.appendChild(script);
  });
  return logoLottieControlsPromise;
}

function installNavCurrentStyles() {
  const style = document.createElement("style");
  style.textContent = `
    .nav, [data-section-navigation] { isolation: isolate; }
    .nav::before, [data-section-navigation]::before {
      content: "";
      position: fixed;
      inset: 0 0 auto;
      height: 180px;
      z-index: -1;
      pointer-events: none;
      opacity: var(--nav-gradient-opacity, 0);
      background: linear-gradient(to bottom, #edff00 0%, rgba(237, 255, 0, 0.82) 38%, rgba(237, 255, 0, 0) 100%);
      transform: translate3d(0, var(--nav-gradient-y, 0px), 0);
      will-change: transform, opacity;
    }
    .nav a.cta.w--current {
      background-color: var(--colour--other-blue);
      color: var(--colour--other-yellow);
    }
  `;
  document.head.appendChild(style);
}

async function boot() {
  await domReady();
  await window.lenisReady;
  app.lenis = window.lenis || (typeof lenis !== "undefined" ? lenis : null);
  const userAgent = navigator.userAgent;
  const isTouchViewport = window.matchMedia("(hover: none), (pointer: coarse)").matches
    || /Android|iPhone|iPad|iPod/i.test(userAgent)
    || (navigator.maxTouchPoints > 1 && /Macintosh/i.test(userAgent));
  if (isTouchViewport) window.ScrollTrigger?.config({ ignoreMobileResize: true });
  startLenisRaf(app.lenis);
  initScrollingBanner(document, app.lenis);
  // This mount lives outside Barba's container and survives every navigation.
  app.three = DISABLE_THREE_FOR_DIAGNOSTICS
    ? null
    : initThreeScene({ mount: document.querySelector("[data-three-canvas]"), lenis: app.lenis });
  if (DISABLE_THREE_FOR_DIAGNOSTICS) console.info("[diagnostics] Three.js scene disabled by ?no3d=1");
  app.barba = initBarba({
    onEnter: runPageSetup,
    onLeave: runPageTeardown,
    onBeforeLeave: ({ container }) => hideFloatingRegister(container),
    onTransitionStart: () => {
      app.lenis?.stop();
    },
    onTransitionComplete: () => {
      app.lenis?.scrollTo(0, { immediate: true });
      app.lenis?.start();
      app.three?.syncScroll();
    },
  });

  if (!app.barba) {
    const container = document.querySelector("[data-barba='container']");
    await runPageSetup({ container });
  }
}

async function runPageSetup({ container, namespace, html, transition = false }) {
  if (!container) return;
  const pageNamespace = String(namespace || container.dataset.barbaNamespace || "page").toLowerCase();
  const setup = async () => {
    container.dataset.pageActive = "true";
    document.body.dataset.page = pageNamespace;
    app.three?.setPage({
      capsule: container.classList.contains("cap2"),
      scrollTarget: container.querySelector("#origin"),
    });
    const Webflow = window.Webflow;
    Webflow?.destroy?.();
    prepareLogoHost(document);
    if (SAFARI_STATIC_LOGO) installStaticLogo(document);
    const incoming = html ? new DOMParser().parseFromString(html, "text/html") : document;
    if (html) {
      const pageId = incoming.documentElement.getAttribute("data-wf-page");
      if (pageId) document.documentElement.setAttribute("data-wf-page", pageId);
    }
    syncNavCurrent(incoming);
    initScrollingBanner(document, app.lenis);
    initSectionNavigation({
      nav: document.querySelector(".nav, [data-section-navigation]"),
      sectionsRoot: container,
      ticker: document.querySelector(".scrolling_banner"),
      lenis: app.lenis,
    });
    initSectionParallax({ root: container, lenis: app.lenis });
    prepareFloatingRegister(container);
    Webflow?.ready?.();
    Webflow?.require?.("ix2")?.init?.();
    initLinkHover(container);
    initFloatingRegister(container);
    if (!SAFARI_STATIC_LOGO && !DISABLE_LOGO_JSON_FOR_DIAGNOSTICS) {
      const controls = await loadLogoLottieControls();
      const { initLogoLottieControls } = controls;
      initLogoLottieControls(document);
    } else if (DISABLE_LOGO_JSON_FOR_DIAGNOSTICS) {
      console.info("[diagnostics] Logo Lottie JSON disabled by ?nojson=1");
    }
    if (ENABLE_LOGO_JITTER && !SAFARI_STATIC_LOGO) initLogoJitter(document);
    container.querySelectorAll("[data-year]").forEach((element) => {
      element.textContent = String(new Date().getFullYear());
    });
  };

  await setup();
  if (!transition) window.ScrollTrigger?.refresh();
}

function syncNavCurrent(page) {
  const activeHref = page.querySelector(".nav a.w--current[href], [data-section-navigation] a.w--current[href]")?.getAttribute("href");
  document.querySelectorAll(".nav a[href], [data-section-navigation] a[href]").forEach((link) => {
    const active = Boolean(activeHref && link.getAttribute("href") === activeHref);
    link.classList.toggle("w--current", active);
    if (active) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
}

function runPageTeardown({ container }) {
  if (!container) return;
  destroySectionNavigation();
  destroySectionParallax();
  destroyScrollingBanner(container);
  destroyLinkHover(container);
  destroyFloatingRegister(container);
  destroyLogoJitter(container);
  delete container.dataset.pageActive;
}

boot().catch((error) => {
  console.error("[base] Setup failed.", error);
});

export { app };
